window.CubeApiDocs.define("api-Risk_Management-修改用户风险控制数据",{"id":"api-Risk_Management-修改用户风险控制数据","versions":[{"version":"1.0.0","toc":[{"id":"overview","title":"用途与调用说明"},{"id":"request-example","title":"请求示例"},{"id":"parameters","title":"路径与通用参数"},{"id":"body","title":"请求体参数"},{"id":"success","title":"成功响应"},{"id":"errors","title":"错误与处理"}],"html":"\u003carticle data-api-id=\"api-Risk_Management-修改用户风险控制数据\">\u003cheader class=\"article-header\">\u003cp class=\"eyebrow\">风险管理 · v1.0.0\u003c/p>\u003ch1 tabindex=\"-1\">修改用户风险控制数据\u003c/h1>\u003cdiv class=\"endpoint\">\u003cspan class=\"method post\">POST\u003c/span>\u003ccode>/riskmgmt/contact/risk/:token\u003c/code>\u003cbutton type=\"button\" data-copy=\"path\" aria-label=\"复制接口路径\">复制路径\u003c/button>\u003c/div>\u003c/header>\u003csection class=\"doc-section\" id=\"overview\">\u003ch2>用途与调用说明\u003c/h2>\u003cp>修改用户的风险控制参数。\u003c/p>\u003c/section>\u003csection class=\"doc-section\" id=\"request-example\">\u003ch2>请求示例\u003c/h2>\u003cdiv class=\"example\">\u003ch3>请求示例\u003c/h3>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"contactId\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token number\">22003303\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"originalMask\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token number\">0\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"forbidSignIn\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token boolean\">true\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"parameters\">\u003ch2>路径与通用参数\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Parameter\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型 / 要求\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>token\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>授权令牌。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"body\">\u003ch2>请求体参数\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"字段说明\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型 / 要求\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>contactId\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>用户的触点ID 。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>originalMask\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>用户的原控制掩码。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>forbidAll\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Boolean\u003c/code>\u003cspan class=\"requirement optional\">可选\u003c/span>\u003c/td>\u003ctd>\u003cp>是否阻止该触点的所有行为。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>forbidSignIn\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Boolean\u003c/code>\u003cspan class=\"requirement optional\">可选\u003c/span>\u003c/td>\u003ctd>\u003cp>是否阻止该触点签入行为。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>forbidSaveFile\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Boolean\u003c/code>\u003cspan class=\"requirement optional\">可选\u003c/span>\u003c/td>\u003ctd>\u003cp>是否阻止该触点保存文件行为。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>forbidDestroyFile\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Boolean\u003c/code>\u003cspan class=\"requirement optional\">可选\u003c/span>\u003c/td>\u003ctd>\u003cp>是否阻止该触点销毁文件行为。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"success\">\u003ch2>成功响应\u003c/h2>\u003cdiv class=\"example\">\u003ch3>应答示例（修改后的风险控制数据）\u003c/h3>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>HTTP/\u003cspan class=\"token number\">1.1\u003c/span> \u003cspan class=\"token number\">200\u003c/span> OK\n\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"contactId\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token number\">22003303\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"mask\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token number\">2\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"forbidAll\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token boolean\">false\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"forbidSignIn\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token boolean\">true\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"forbidSaveFile\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token boolean\">false\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"forbidDestroyFile\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token boolean\">false\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/div>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Success 200\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>contactId\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003c/td>\u003ctd>\u003cp>用户的触点ID 。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>mask\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003c/td>\u003ctd>\u003cp>触点风险控制掩码。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>forbidAll\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Boolean\u003c/code>\u003c/td>\u003ctd>\u003cp>是否阻止该触点的所有行为。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>forbidSignIn\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Boolean\u003c/code>\u003c/td>\u003ctd>\u003cp>是否阻止该触点签入行为。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>forbidSaveFile\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Boolean\u003c/code>\u003c/td>\u003ctd>\u003cp>是否阻止该触点保存文件行为。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>forbidDestroyFile\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Boolean\u003c/code>\u003c/td>\u003ctd>\u003cp>是否阻止该触点销毁文件行为。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"errors\">\u003ch2>错误与处理\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Error 4xx\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>400\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>服务器错误。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>401\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>Token 无效。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>403\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>参数错误。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>404\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>设置参数时发生错误。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003c/article>"}]});
